const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>{if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return null;const time=Date.parse(value+'T12:00:00Z');return Number.isFinite(time)&&new Date(time).toISOString().slice(0,10)===value?value:null;};
const valid=h=>h&&typeof h.text==='string'&&h.text.trim()&&h.text.length<=2000;
export function homeworkMarkup(homework){
 if(!valid(homework))return '';
 const due=date(homework.dueDate),label=due?new Intl.DateTimeFormat('ru-RU',{timeZone:'UTC',day:'numeric',month:'long',year:'numeric'}).format(Date.parse(due+'T12:00:00Z')):null;
 return '<section class="lesson-homework-card" aria-label="Домашнее задание"><h3>Домашнее задание</h3><p class="lesson-homework-text" dir="auto">'+esc(homework.text)+'</p>'+(label?'<p class="lesson-homework-due">Срок: '+esc(label)+'</p>':'')+'</section>';
}
export function mountHomeworkEditor(root,{lesson,onSave,onCancel=()=>{}}){
 let disposed=false,readingEditor=null,readingLoading=null,readingCleared=false;const initial=valid(lesson.homework)?lesson.homework:null,minimum=date(lesson.date);
 root.innerHTML='<form class="lesson-homework-editor"><h2>Домашнее задание</h2><p>'+esc(lesson.title)+'</p><label>Задание<textarea name="homework" rows="5" maxlength="2000" placeholder="Что ученикам нужно повторить или подготовить">'+esc(initial?.text||'')+'</textarea></label><small>До 2000 символов. Задание можно добавить до, во время или после занятия.</small><label>Срок сдачи · по желанию<input name="dueDate" type="date"'+(minimum?' min="'+minimum+'"':'')+' value="'+esc(date(initial?.dueDate)||'')+'"></label><div data-reading-editor><button type="button" class="button secondary" data-add-reading>Проверка после пройденной буквы · по желанию</button></div><p role="alert" class="lesson-homework-error"></p><div class="button-row"><button class="button" type="submit">Сохранить ДЗ</button><button class="button secondary" type="button" data-cancel>Закрыть</button>'+(initial?'<button class="lesson-text-button" type="button" data-clear>Убрать задание</button>':'')+'</div></form>';
 const form=root.querySelector('form'),button=form.querySelector('[type=submit]'),text=form.querySelector('textarea'),due=form.querySelector('input'),error=form.querySelector('[role=alert]');
 const readingRoot=form.querySelector('[data-reading-editor]');const openReading=(initial,createDefault=false)=>{if(readingLoading)return readingLoading;readingLoading=import('./reading-check-ui.js').then(module=>{if(disposed||!root.isConnected)return;readingEditor=module.mountReadingCheckEditor(readingRoot,{initial:readingCleared?null:createDefault?{version:1,letterId:'mim',count:10,prompts:module.readingExamples('mim',10)}:initial,onChange:()=>{readingCleared=false;}});}).catch(error=>{if(!disposed)form.querySelector('[role=alert]').textContent='Не удалось открыть проверку. Повторите.';throw error;}).finally(()=>{readingLoading=null;});return readingLoading;};readingRoot.querySelector('button').onclick=()=>void openReading(null,true).catch(()=>{});if(initial?.readingCheck)void openReading(initial.readingCheck).catch(()=>{});
 form.querySelector('[data-cancel]').onclick=()=>{if(!disposed)onCancel();};
 form.querySelector('[data-clear]')?.addEventListener('click',()=>{text.value='';due.value='';readingEditor?.disable();readingCleared=true;error.textContent='Задание будет убрано после нажатия «Сохранить ДЗ».';text.focus();});
 form.onsubmit=async event=>{event.preventDefault();if(disposed||button.disabled)return;if(text.value.length>2000){error.textContent='Сократите задание до 2000 символов.';return;}if(readingLoading){button.disabled=true;try{await readingLoading;}catch{button.disabled=false;return;}button.disabled=false;}if(disposed||!form.isConnected)return;let readingCheck;try{readingCheck=readingCleared?null:readingEditor?readingEditor.value():initial?.readingCheck||null;}catch(e){error.textContent=e.message;return;}let content=text.value.trim();if(readingCheck&&!content)content='Прочитайте сочетания после пройденной буквы и отправьте голосовую запись до следующего занятия.';if(!content&&due.value){error.textContent='Добавьте текст задания или очистите срок.';return;}if(!form.checkValidity())return;button.disabled=true;error.textContent='';try{await onSave(content?{text:content,dueDate:due.value||null,...(readingCheck?{readingCheck}:{})}:null,lesson.homeworkRevision||0);}catch(e){if(!disposed&&form.isConnected){error.textContent=e.message||'Не удалось сохранить ДЗ.';button.disabled=false;}}};
 text.focus();return()=>{disposed=true;readingEditor?.dispose();form.onsubmit=null;root.replaceChildren();};
}
